// Checkout conversion module - ensures paidEvents are tracked
const fs = require('fs');
const path = require('path');

const REVENUE_LOG = '/var/log/revenue_events.log';

function logPaidEvent(details) {
  const entry = {
    ts: new Date().toISOString(),
    type: 'paid',
    ...details
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(entry) + '\n');
  // Also update in-memory counter via a simple file
  const counterPath = '/tmp/paid_events_counter';
  let count = 0;
  try {
    count = parseInt(fs.readFileSync(counterPath, 'utf8')) || 0;
  } catch (e) {}
  count++;
  fs.writeFileSync(counterPath, String(count));
  return count;
}

function getPaidEventCount() {
  const counterPath = '/tmp/paid_events_counter';
  try {
    return parseInt(fs.readFileSync(counterPath, 'utf8')) || 0;
  } catch (e) {
    return 0;
  }
}

module.exports = { logPaidEvent, getPaidEventCount };
